/// Shape Position Coordinate (ECMA-376 Part 1 §20.1.9.17).
///
/// Specifies a position coordinate within the shape bounding box. It should be noted that this coordinate is placed within the shape bounding box using the transform coordinate system which is also called the shape coordinate system, as it encompasses the entire shape. The width and height for this coordinate system are specified within the ext transform element.
///
/// Schema type `CT_AdjPoint2D`, used by:
///
/// * `a:pos` — Shape Position Coordinate (§20.1.9.17)
/// * `a:pt` — Shape Path Point (§20.1.9.20)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_AdjPoint2D {
    /// `x` — X-Coordinate. Specifies the x coordinate for this position coordinate. Required by the schema.
    pub x: Option<ST_AdjCoordinate>,
    /// `y` — Y-Coordinate. Specifies the y coordinate for this position coordinate. Required by the schema.
    pub y: Option<ST_AdjCoordinate>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_AdjPoint2D {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "x") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.x = Some(v);
                        continue;
                    }
                }
                (Ns::NONE, "y") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.y = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            while let Some(child) = r.next_child()? {
                let raw = RawElement::read(r, &child)?;
                rt::push_extra(&mut this.extra_children, 0, raw);
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_AdjPoint2D {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "x", &self.x);
        rt::write_attr(w, Ns::NONE, "y", &self.y);
        w.attrs_raw(&self.extra_attrs);
        rt::write_extras(w, &self.extra_children, 0);
        w.end();
    }
}

impl Validate for CT_AdjPoint2D {
    fn validate(&self, v: &mut Validator) {
        if self.x.is_none() {
            v.required_attribute(Ns::NONE, "x", &self.extra_attrs);
        }
        if self.y.is_none() {
            v.required_attribute(Ns::NONE, "y", &self.extra_attrs);
        }
    }
}

/// List of Shape Adjust Handles (ECMA-376 Part 1 §20.1.9.1).
///
/// This element specifies the adjust handles that are applied to a custom geometry. These adjust handles specify points within the geometric shape that can be used to perform certain transform operations on the shape.
///
/// Schema type `CT_AdjustHandleList`, used by:
///
/// * `a:ahLst` — List of Shape Adjust Handles (§20.1.9.1)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_AdjustHandleList {
    /// Child elements of choice [`CT_AdjustHandleList_Choice`](crate::dml::CT_AdjustHandleList_Choice).
    pub choice: Vec<CT_AdjustHandleList_Choice>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_AdjustHandleList {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::A, "ahXY") | (Ns::A, "ahPolar") => {
                        this.choice
                            .push(CT_AdjustHandleList_Choice::read_choice(r, &child)?);
                        pos = 1;
                    }
                    _ => {
                        match pos {
                            1 => this.choice.push(CT_AdjustHandleList_Choice::Other(Box::new(
                                RawElement::read(r, &child)?,
                            ))),
                            _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                        }
                    }
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_AdjustHandleList {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        w.attrs_raw(&self.extra_attrs);
        rt::write_extras(w, &self.extra_children, 0);
        for v in &self.choice {
            v.write_choice(w);
        }
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_AdjustHandleList {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.choice.iter().enumerate() {
            x.validate_at(v, Some(i));
        }
    }
}

