                        if this.cust_clr_lst.is_none() {
                            this.cust_clr_lst = Some(Box::new(XmlRead::read_xml(r, &child)?));
                        } else {
                            rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?);
                        }
