/// Preset Color (ECMA-376 Part 1 §20.1.2.3.22).
///
/// This element specifies a color which is bound to one of a predefined collection of colors.
///
/// Schema type `CT_PresetColor`, used by:
///
/// * `a:prstClr` — Preset Color (§20.1.2.3.22)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_PresetColor {
    /// `val` — Value. Specifies the actual preset color value. Required by the schema.
    pub val: Option<ST_PresetColorVal>,
    /// Child elements of choice [`EG_ColorTransform`](crate::dml::EG_ColorTransform).
    pub color_transform: Vec<EG_ColorTransform>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_PresetColor {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            match (a.ns, a.local) {
                (Ns::NONE, "val") => {
                    if let Some(v) = XmlValue::parse_xml(&a.value) {
                        this.val = Some(v);
                        continue;
                    }
                }
                _ => {}
            }
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::A, "tint")
                    | (Ns::A, "shade")
                    | (Ns::A, "comp")
                    | (Ns::A, "inv")
                    | (Ns::A, "gray")
                    | (Ns::A, "alpha")
                    | (Ns::A, "alphaOff")
                    | (Ns::A, "alphaMod")
                    | (Ns::A, "hue")
                    | (Ns::A, "hueOff")
                    | (Ns::A, "hueMod")
                    | (Ns::A, "sat")
                    | (Ns::A, "satOff")
                    | (Ns::A, "satMod")
                    | (Ns::A, "lum")
                    | (Ns::A, "lumOff")
                    | (Ns::A, "lumMod")
                    | (Ns::A, "red")
                    | (Ns::A, "redOff")
                    | (Ns::A, "redMod")
                    | (Ns::A, "green")
                    | (Ns::A, "greenOff")
                    | (Ns::A, "greenMod")
                    | (Ns::A, "blue")
                    | (Ns::A, "blueOff")
                    | (Ns::A, "blueMod")
                    | (Ns::A, "gamma")
                    | (Ns::A, "invGamma") => {
                        this.color_transform
                            .push(EG_ColorTransform::read_choice(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => this
                            .color_transform
                            .push(EG_ColorTransform::Other(Box::new(RawElement::read(r, &child)?))),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_PresetColor {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        rt::write_attr(w, Ns::NONE, "val", &self.val);
        w.attrs_raw(&self.extra_attrs);
        rt::write_extras(w, &self.extra_children, 0);
        for v in &self.color_transform {
            v.write_choice(w);
        }
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_PresetColor {
    fn validate(&self, v: &mut Validator) {
        if self.val.is_none() {
            v.required_attribute(Ns::NONE, "val", &self.extra_attrs);
        }
        for (i, x) in self.color_transform.iter().enumerate() {
            x.validate_at(v, Some(i));
        }
    }
}

